1	"use client";
2	
3	import { useEffect, useState, useTransition } from "react";
4	import { createPortal } from "react-dom";
5	// Namespace import (never named): a computed key lookup can't produce an
6	// "export not found" build error, so an unknown/removed brand simply renders
7	// nothing and the button falls back to its plain label. Same pattern as
8	// components/marketing/CompetitorLogo.tsx.
9	import * as simpleIcons from "simple-icons";
10	import { IconUsers } from "@/components/marketing/icons";
11	import { setHeardAboutUs } from "@/lib/actions-account";
12	import { HEARD_OPTIONS, HEARD_OTHER_MAX } from "@/lib/heard-about";
13	
14	type SimpleIcon = { title: string; slug: string; hex: string; path: string };
15	
16	/** Channel key → Simple Icons export name, for the real platforms we can
17	 *  scrape an accurate vector brand mark for. `color` overrides the brand's
18	 *  own hex only when that hex is near-black (TikTok, X) and would otherwise
19	 *  vanish on this modal's dark card background. */
20	const HEARD_BRAND_ICON: Record<string, { key: string; color?: string }> = {
21	  google: { key: "siGoogle" },
22	  youtube: { key: "siYoutube" },
23	  instagram: { key: "siInstagram" },
24	  tiktok: { key: "siTiktok", color: "#FFFFFF" },
25	  facebook: { key: "siFacebook" },
26	  x: { key: "siX", color: "#FFFFFF" },
27	  reddit: { key: "siReddit" },
28	  // simple-icons has no separate "ChatGPT" mark — OpenAI's is the closest real
29	  // brand icon (same relationship as a customer saying "ChatGPT" to mean the
30	  // OpenAI product). Label stays "ChatGPT" (lib/heard-about.ts); only the icon
31	  // is OpenAI's.
32	  chatgpt: { key: "siOpenai" },
33	};
34	
35	/** Real vector brand mark for a platform channel, or null when the key isn't
36	 *  one of the platforms above (the non-platform options use hand-drawn line
37	 *  icons instead — see below). */
38	function BrandIcon({ channelKey, size = 22 }: { channelKey: string; size?: number }) {
39	  const entry = HEARD_BRAND_ICON[channelKey];
40	  const icon = entry ? ((simpleIcons as Record<string, unknown>)[entry.key] as SimpleIcon | undefined) : undefined;
41	  if (!icon || typeof icon.path !== "string") return null;
42	  return (
43	    <svg role="img" aria-hidden viewBox="0 0 24 24" style={{ height: size, width: size }}>
44	      <path d={icon.path} fill={entry?.color ?? `#${icon.hex}`} />
45	    </svg>
46	  );
47	}
48	
49	/** Shared stroke style for the non-platform line icons below — same visual
50	 *  language as components/marketing/icons.tsx and PaymentStep.tsx's inline
51	 *  icons (24×24, stroke=currentColor), so they inherit the button's text
52	 *  color and adapt to the selected state automatically. */
53	function LineIcon({ size = 22, children }: { size?: number; children: React.ReactNode }) {
54	  return (
55	    <svg
56	      width={size}
57	      height={size}
58	      viewBox="0 0 24 24"
59	      fill="none"
60	      stroke="currentColor"
61	      strokeWidth="1.7"
62	      strokeLinecap="round"
63	      strokeLinejoin="round"
64	      aria-hidden
65	    >
66	      {children}
67	    </svg>
68	  );
69	}
70	
71	function OtherIcon(p: { size?: number }) {
72	  return (
73	    <LineIcon {...p}>
74	      <circle cx="12" cy="12" r="9" />
75	      <path d="M9.4 9.2a2.6 2.6 0 1 1 3.7 2.35c-.85.4-1.1.95-1.1 1.75" />
76	      <circle cx="12" cy="16.9" r="0.9" fill="currentColor" stroke="none" />
77	    </LineIcon>
78	  );
79	}
80	
81	/** Icon for a HEARD_OPTIONS key (or "other"): the real brand mark for a
82	 *  platform, a matching line icon for the non-platform options, or null. */
83	function optionIcon(key: string): React.ReactNode {
84	  if (HEARD_BRAND_ICON[key]) return <BrandIcon channelKey={key} />;
85	  if (key === "friend") return <IconUsers size={22} />;
86	  if (key === "other") return <OtherIcon />;
87	  return null;
88	}
