90	/**
91	 * One-time "How did you hear about us?" acquisition survey.
92	 *
93	 * Rendered from the dashboard layout ONLY when the signed-in customer's
94	 * `heardAboutUs` is still null and no admin is impersonating them. The layout's
95	 * server-side null check is the real gate — this component just shows the modal
96	 * once and then closes for good. The write itself is idempotent
97	 * (setHeardAboutUs only sets when null), so even a double-submit is safe.
98	 *
99	 * The overlay is portaled to document.body: the portal (Shell) wraps content in
100	 * transformed ancestors, and a `position: fixed` node inside a transformed
101	 * parent anchors to THAT parent, not the viewport — dropping the modal down the
102	 * page. Same fix as components/admin/EmailLogViewer.tsx.
103	 */
104	export function HeardAboutUsPrompt() {
105	  // Local visibility. Starts open because the parent only mounts us when the
106	  // server says heardAboutUs is null; once dismissed it never comes back this
107	  // session, and the null→value transition keeps it gone on future loads.
108	  const [open, setOpen] = useState(true);
109	  const [choice, setChoice] = useState<string | null>(null);
110	  const [otherText, setOtherText] = useState("");
111	  const [pending, startTransition] = useTransition();
112	  /* `typeof document === "undefined"` checked DURING RENDER (not in an
113	     effect) is itself a hydration-mismatch bug, not a fix for one — it's the
114	     exact "if (typeof window !== 'undefined')" branch React's own hydration
115	     error message calls out by name. The server takes the false branch
116	     (no document), but the client's FIRST render — the one hydration
117	     compares against the server's HTML — takes the true branch immediately
118	     (document exists in the browser), so this always mismatched. Worse,
119	     since createPortal renders nothing during SSR by design (no DOM to
120	     portal into), the server's output for this component was already
121	     "nothing" while the client inserted the real modal into document.body
122	     on that same first pass — confirmed live via React's dev-mode hydration
123	     diff (`- <Suspense>` / `+ <div className="fixed inset-0 z-[70]...">`)
124	     after registering a fresh account and landing on /dashboard, and
125	     plausibly behind reports of the dashboard/deploy page getting stuck
126	     mid-render, since a discarded/regenerated subtree this high in the tree
127	     (a direct child of <main>) has a lot of siblings to take down with it.
128	     `mounted` gates the portal until AFTER hydration has already committed,
129	     so the very first client render agrees with the server (nothing here),
130	     and the reveal happens in a separate, safe, post-hydration render. */
131	  const [mounted, setMounted] = useState(false);
132	  useEffect(() => setMounted(true), []);
133	
134	  if (!open || !mounted) return null;
135	
136	  const submit = (source: string) => {
137	    // Close optimistically — the answer is fire-and-forget and the server is the
138	    // source of truth for "asked once", so we never need to reopen on failure.
139	    setOpen(false);
140	    startTransition(async () => {
141	      try {
142	        await setHeardAboutUs(source);
143	      } catch {
144	        /* best-effort: a failed survey write must never surface an error */
145	      }
146	    });
147	  };
148	
149	  const answer = () => {
150	    if (!choice) return;
151	    if (choice === "other") {
152	      const text = otherText.trim();
153	      submit(text ? `other:${text}` : "other");
154	    } else {
155	      submit(choice);
156	    }
157	  };
158	
159	  const canSubmit = choice !== null && (choice !== "other" || otherText.trim().length > 0);
160	
161	  return createPortal(
162	    <div
163	      className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"
164	      role="dialog"
165	      aria-modal="true"
166	      aria-labelledby="heard-title"
167	    >
168	      <div className="card w-full max-w-lg p-6 motion-safe:animate-panel-in" onClick={(e) => e.stopPropagation()}>
169	        <h2 id="heard-title" className="text-lg font-bold tracking-tight">
170	          How did you hear about us?
171	        </h2>
172	        <p className="mt-1 text-sm text-slate-400">
173	          Quick one-tap question — it helps us reach more people like you. This won&apos;t be asked again.
174	        </p>
175	
176	        <div className="mt-5 grid grid-cols-2 gap-2 sm:grid-cols-3">
177	          {HEARD_OPTIONS.map((o) => (
178	            <button
179	              key={o.key}
180	              type="button"
181	              onClick={() => setChoice(o.key)}
182	              aria-pressed={choice === o.key}
183	              className={`flex flex-col items-center gap-1.5 rounded-xl border px-3 py-3 text-sm font-medium transition-colors ${
184	                choice === o.key
185	                  ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
186	                  : "border-white/10 bg-white/[0.03] text-slate-300 hover:border-white/20 hover:bg-white/[0.06]"
187	              }`}
188	            >
189	              {optionIcon(o.key)}
190	              <span>{o.label}</span>
191	            </button>
192	          ))}
193	          <button
194	            type="button"
195	            onClick={() => setChoice("other")}
196	            aria-pressed={choice === "other"}
197	            className={`flex flex-col items-center gap-1.5 rounded-xl border px-3 py-3 text-sm font-medium transition-colors ${
198	              choice === "other"
199	                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
200	                : "border-white/10 bg-white/[0.03] text-slate-300 hover:border-white/20 hover:bg-white/[0.06]"
201	            }`}
202	          >
203	            <OtherIcon />
204	            <span>Other</span>
205	          </button>
206	        </div>
207	
208	        {choice === "other" && (
209	          <div className="mt-3">
210	            <input
211	              type="text"
212	              autoFocus
213	              value={otherText}
214	              maxLength={HEARD_OTHER_MAX}
215	              onChange={(e) => setOtherText(e.target.value)}
216	              onKeyDown={(e) => {
217	                if (e.key === "Enter" && canSubmit) answer();
218	              }}
219	              placeholder="Tell us where…"
220	              className="input"
221	            />
222	          </div>
223	        )}
224	
225	        <div className="mt-6 flex items-center justify-between gap-3">
226	          <button type="button" onClick={() => submit("skipped")} disabled={pending} className="btn-ghost text-sm">
227	            Skip
228	          </button>
229	          <button type="button" onClick={answer} disabled={!canSubmit || pending} className="btn-primary">
230	            Submit
231	          </button>
232	        </div>
233	      </div>
234	    </div>,
235	    document.body,
236	  );
237	}
238	
239	export default HeardAboutUsPrompt;
