1	/**
2	 * Shared vocabulary for the one-time "How did you hear about us?" acquisition
3	 * survey (User.heardAboutUs). ONE definition of the channel keys, their friendly
4	 * labels, and the value validation — imported by the customer prompt
5	 * (components/customer/HeardAboutUsPrompt.tsx), the server action
6	 * (lib/actions-account.ts), the admin aggregate (app/admin/audience/page.tsx)
7	 * and the customer profile (app/admin/users/[id]/page.tsx) so none of the four
8	 * can drift out of step with the others.
9	 *
10	 * This module is intentionally framework-free (no "use server", no server-only
11	 * imports) so the client prompt can import the option list and labels too.
12	 *
13	 * Stored value shapes (User.heardAboutUs):
14	 *   null              — not yet asked / not yet answered
15	 *   "skipped"         — the customer dismissed the survey
16	 *   "<channel key>"   — one of HEARD_OPTIONS below (google, youtube, …, blog)
17	 *   "other:<text>"    — the free-text "Other" answer (text trimmed + capped)
18	 */
19	
20	/** The selectable channels, in display order. "other" is handled separately
21	 *  because it carries a free-text tail; it is not in this list. */
22	export const HEARD_OPTIONS = [
23	  { key: "google", label: "Google Search" },
24	  { key: "youtube", label: "YouTube" },
25	  { key: "instagram", label: "Instagram" },
26	  { key: "tiktok", label: "TikTok" },
27	  { key: "facebook", label: "Facebook" },
28	  { key: "x", label: "X (Twitter)" },
29	  { key: "reddit", label: "Reddit" },
30	  { key: "friend", label: "Friend / word of mouth" },
31	  { key: "chatgpt", label: "ChatGPT" },
32	] as const;
33	
34	export type HeardChannelKey = (typeof HEARD_OPTIONS)[number]["key"];
35	
36	/** key → friendly label, including the "other" bucket. The single source the
37	 *  prompt, the aggregate and the profile all read from. */
38	export const HEARD_LABELS: Record<string, string> = {
39	  ...Object.fromEntries(HEARD_OPTIONS.map((o) => [o.key, o.label])),
40	  other: "Other",
41	  // "blog" was retired from HEARD_OPTIONS (replaced by "chatgpt") but real
42	  // customers already answered it — keep the label so their historical
43	  // answers don't render as a raw key in admin views. Not selectable again:
44	  // normalizeHeardSource only accepts CHANNEL_KEYS, which is derived from
45	  // HEARD_OPTIONS and no longer includes it.
46	  blog: "Blog / article",
47	};
48	
49	/** Set of concrete channel keys that are valid on their own (no free text). */
50	const CHANNEL_KEYS = new Set<string>(HEARD_OPTIONS.map((o) => o.key));
51	
52	/** Max length of the free-text tail on an "other:<text>" answer. */
53	export const HEARD_OTHER_MAX = 120;
54	
55	/** Sanitize the free text a customer types into the "Other" box: drop control
56	 *  characters, collapse whitespace, trim and cap length. */
57	export function sanitizeHeardOther(text: string): string {
58	  const cleaned = Array.from(text)
59	    .filter((ch) => {
60	      const c = ch.codePointAt(0) ?? 0;
61	      // Drop C0 controls (incl. tab/newline) and DEL; keep everything else.
62	      return c >= 0x20 && c !== 0x7f;
63	    })
64	    .join("");
65	  return cleaned.replace(/\s+/g, " ").trim().slice(0, HEARD_OTHER_MAX);
66	}
67	
68	/**
69	 * Validate/normalize a raw survey submission into a value safe to store, or
70	 * `null` when it is not a recognised answer (the action then no-ops rather than
71	 * writing garbage). Accepts a bare channel key, "skipped", or "other:<text>".
72	 */
73	export function normalizeHeardSource(raw: unknown): string | null {
74	  if (typeof raw !== "string") return null;
75	  const value = raw.trim();
76	  if (value === "skipped") return "skipped";
77	  if (CHANNEL_KEYS.has(value)) return value;
78	  if (value === "other" || value.toLowerCase().startsWith("other:")) {
79	    const tail = value.slice(value.indexOf(":") + 1);
80	    const text = value === "other" ? "" : sanitizeHeardOther(tail);
81	    return text ? `other:${text}` : "other";
82	  }
83	  return null;
84	}
85	
86	/**
87	 * Friendly display label for a stored value. `null` → "—", "skipped" →
88	 * "Skipped", any "other:<text>" → "Other" (with the typed text appended when
89	 * `withOtherText`), otherwise the channel's friendly label.
90	 */
91	export function heardLabel(value: string | null | undefined, opts?: { withOtherText?: boolean }): string {
92	  if (value == null || value === "") return "—";
93	  if (value === "skipped") return "Skipped";
94	  if (value === "other" || value.startsWith("other:")) {
95	    const text = value.startsWith("other:") ? value.slice("other:".length).trim() : "";
96	    return opts?.withOtherText && text ? `Other — ${text}` : "Other";
97	  }
98	  return HEARD_LABELS[value] ?? value;
99	}
100	
101	/** Bucket key used by the aggregate: every "other:<text>" collapses to "other". */
102	export function heardBucket(value: string): string {
103	  return value.startsWith("other:") ? "other" : value;
104	}
