100	export default async function DashboardLayout({ children }: { children: React.ReactNode }) {
101	  const user = await currentUser();
102	  if (!user) redirect("/login");
103	  const imp = await impersonating();
104	
105	  // Maintenance mode: gate the whole customer portal for non-admins. Admins (and
106	  // admins impersonating a customer) always pass so they can keep working. This
107	  // only covers the dashboard tree — /login and /admin have their own layouts.
108	  if (user.role !== "ADMIN" && (await getSettingBool("maintenance_mode", false))) {
109	    const message = await getSetting("maintenance_message");
110	    return (
111	      <main
112	        style={{
113	          minHeight: "100vh",
114	          display: "flex",
115	          flexDirection: "column",
116	          alignItems: "center",
117	          justifyContent: "center",
118	          gap: "1rem",
119	          padding: "2rem",
120	          textAlign: "center",
121	        }}
122	      >
123	        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Down for maintenance</h1>
124	        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>{message}</p>
125	      </main>
126	    );
127	  }
128	
129	  // Hide nav entries whose feature flag is disabled (secondary to the server-side
130	  // refusals in the order/create actions).
131	  const flags: Record<string, boolean> = {
132	    feature_game_servers: await getSettingBool("feature_game_servers", true),
133	    feature_claude_builder: await getSettingBool("feature_claude_builder", true),
134	    feature_domains: await getSettingBool("feature_domains", true),
135	    feature_referrals: await getSettingBool("feature_referrals", true),
136	    // Off by default — hidden until publishing / the feature is live (see FEATURE_HREF).
137	    feature_website_builder: await getSettingBool("feature_website_builder", false),
138	    feature_calendar: await getSettingBool("feature_calendar", false),
139	  };
140	  const visibleNav: NavSection[] = nav
141	    .map((section) => ({
142	      ...section,
143	      items: section.items.filter((item) => {
144	        const flag = FEATURE_HREF[item.href];
145	        return !flag || flags[flag];
146	      }),
147	    }))
148	    .filter((section) => section.items.length > 0);
149	
150	  const notifications = await db.notification.findMany({
151	    where: { userId: user.id },
152	    orderBy: { createdAt: "desc" },
153	    take: 15,
154	  });
155	
156	  // Support badge: this customer's own tickets awaiting a staff reply
157	  // (their newly opened tickets + threads where they replied last). Fails soft.
158	  const supportAwaiting = await db.ticket
159	    .count({ where: { userId: user.id, status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })
160	    .catch(() => 0);
161	  const navWithBadges: NavSection[] = visibleNav.map((section) => ({
162	    ...section,
163	    items: section.items.map((item) =>
164	      item.href === "/dashboard/support" && supportAwaiting > 0
165	        ? { ...item, badge: supportAwaiting }
166	        : item
167	    ),
168	  }));
169	
170	  // Provide the display-currency context to the portal so browse/catalog prices
171	  // can localize. DISPLAY ONLY: wallet balances, invoices and any actual CHARGE
172	  // amount must stay in USD and are NOT routed through this — see the boundary
173	  // note in lib/currency.ts. Only components that explicitly opt in via
174	  // `useDisplayMoney()` convert; nothing here is auto-converted.
175	  const { currency: displayCurrency, rates: fxRates } = await resolveDisplayCurrency();
176	
177	  return (
178	    <CurrencyProvider initialCurrency={displayCurrency} rates={fxRates}>
179	    {/* Badges for the designed rail. `supportAwaiting` is already computed
180	        above for the portal shell's own nav; this reuses it rather than
181	        counting the same tickets a second time. */}
182	    {/* The Nexion shell, ported verbatim from the design sandbox. It takes the
183	        session user and nothing else — the nav is the designed twelve-item rail
184	        (lib/nx/nav.ts), not the portal's generated one.
185	
186	        STILL TO PORT from components/portal/Shell: the notifications panel and
187	        the impersonation banner. Both are real features with no counterpart in
188	        the design yet; they are not lost, just not drawn here. Design them, then
189	        wire `notifications` / `impersonation` back in. */}
190	    <Shell
191	      user={{ first: user.name.split(" ")[0], email: user.email, balanceCents: user.balanceCents }}
192	      badges={{ "/dashboard/support": supportAwaiting }}
193	      notifications={notifications.map((n) => ({
194	        id: n.id,
195	        title: n.title,
196	        body: n.body,
197	        href: n.href,
198	        readAt: n.readAt ? n.readAt.toISOString() : null,
199	        createdAt: n.createdAt.toISOString(),
200	      }))}
201	    >
202	      {/* Impersonation goes FIRST and is never dismissible — an admin who
203	          forgets which account they are in is the expensive failure here. */}
204	      {imp && <ImpersonationBanner adminName={imp.admin.name} targetEmail={imp.target.email} />}
205	      {/* Unverified accounts browse the whole portal freely; only buying is
206	          gated (lib/email-verification.ts). The prompt lives here rather than at
207	          checkout so the customer meets the prerequisite while it is cheap to
208	          fix, instead of meeting it with a card in their hand. Hidden while an
209	          admin is impersonating: it is not the admin's address to confirm, and
210	          the resend button would mail the customer from inside someone else's
211	          session. */}
212	      {!imp && !isEmailVerified(user) && !isGrandfathered(user) && (
213	        <VerifyEmailBanner email={user.email} />
214	      )}
215	      {/* Admin broadcasts — dismissible per-user. Soft-fails to nothing so a
216	          broadcast query problem can never take down the portal. */}
217	      <AnnouncementBanner announcements={await activeAnnouncementsForUser().catch(() => [])} />
218	      {/* Fires the Meta/Google Purchase conversion when a freshly-paid order lands on
219	          any dashboard route (fulfil-checkout tags the redirect). No-op otherwise. */}
220	      <PurchaseTracker />
221	      {/* Fires the "signup" conversion once when a freshly-registered account lands
222	          here (register() redirects to ?signup=1). Strips the marker; no-op otherwise. */}
223	      <SignupTracker />
224	      {/* Kodely (or any future partner) deep link (?ref=kodely) -> a short-lived
225	          cookie so payAndDeploy/purchaseDomain can attribute the order without
226	          threading the param through every wizard step. */}
227	      <PartnerSourceCapture />
228	      {/* One-time "How did you hear about us?" survey. Only when the account has
229	          not answered yet (heardAboutUs is null) and NOT while an admin is
230	          impersonating — the admin must never answer the survey on the
231	          customer's behalf. The server action is itself guarded to write only
232	          when null, so this is a UI gate over an idempotent write. */}
233	      {!imp && user.heardAboutUs == null && <HeardAboutUsPrompt />}
234	      {/* Update announcements popup — shows unseen service updates one at a
235	          time. Fetches client-side (no SSR delay) and soft-fails to nothing. */}
236	      <AnnouncementPopup />
237	      {children}
238	    </Shell>
239	    </CurrencyProvider>
240	  );
241	}
