21	// ---------- Profile ----------
22	
23	export async function updateProfile(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
24	  const user = await requireUser();
25	  const name = String(formData.get("name") ?? "").trim();
26	  if (name.length < 1 || name.length > 100) return { error: "Enter a valid name." };
27	  await db.user.update({ where: { id: user.id }, data: { name } });
28	  revalidatePath("/dashboard/settings");
29	  return { ok: true };
30	}
31	
32	export async function changePassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
33	  const user = await requireUser();
34	  const current = String(formData.get("current") ?? "");
35	  const next = String(formData.get("next") ?? "");
36	  if (next.length < 8) return { error: "New password must be at least 8 characters." };
37	  if (!(await bcrypt.compare(current, user.passwordHash))) return { error: "Current password is incorrect." };
38	  // Bump sessionVersion to evict every other outstanding session, then re-issue a
39	  // fresh token for THIS session so the user who changed the password stays in.
40	  await db.user.update({
41	    where: { id: user.id },
42	    data: { passwordHash: await bcrypt.hash(next, 12), sessionVersion: { increment: 1 } },
43	  });
44	  await createSession(user.id);
45	  return { ok: true };
46	}
