48	/**
49	 * Evict every OTHER logged-in session for this account (a stolen/borrowed device,
50	 * a shared computer left signed in) while keeping the caller signed in. Same
51	 * mechanism as a password change: bump sessionVersion so every existing token
52	 * fails the version check, then re-issue a fresh token for THIS session.
53	 */
54	export async function signOutOtherSessions(): Promise<{ ok?: boolean; error?: string }> {
55	  const user = await requireUser();
56	  await db.user.update({
57	    where: { id: user.id },
58	    data: { sessionVersion: { increment: 1 } },
59	  });
60	  await createSession(user.id);
61	  return { ok: true };
62	}
