65	
66	/**
67	 * Record the customer's answer to the one-time acquisition survey.
68	 *
69	 * `source` is validated against the allowed channel keys + "skipped" + the
70	 * "other:<free text>" shape (the free text is trimmed, control-stripped and
71	 * capped ~120 chars — see normalizeHeardSource). An unrecognised value is
72	 * silently dropped.
73	 *
74	 * "Asked once" is enforced at the write: we only set heardAboutUs when it is
75	 * still null, using an `updateMany` guarded by `heardAboutUs: null`. A second
76	 * call (or a race between two tabs) after any value — a channel OR "skipped" —
77	 * is a no-op and never overwrites the first answer. Always returns { ok: true }
78	 * so the client can close the prompt regardless.
79	 */
80	export async function setHeardAboutUs(source: string): Promise<{ ok: true }> {
81	  const user = await requireUser();
82	  const value = normalizeHeardSource(source);
83	  if (!value) return { ok: true };
84	  await db.user.updateMany({
85	    where: { id: user.id, heardAboutUs: null },
86	    data: { heardAboutUs: value },
87	  });
88	  return { ok: true };
89	}
