94	  const user = await requireUser();
95	  const parsed = z
96	    .object({
97	      name: z.string().min(1).max(60),
98	      publicKey: z.string().min(20).max(4000).regex(/^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/, "Not a valid OpenSSH public key"),
99	    })
100	    .safeParse({ name: formData.get("name"), publicKey: String(formData.get("publicKey") ?? "").trim() });
101	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid key." };
102	  await db.sshKey.create({ data: { userId: user.id, ...parsed.data } });
103	  revalidatePath("/dashboard/settings");
