154	// ---------- Password reset (email-based) ----------
155	
156	export async function requestPasswordReset(prev: any, formData: FormData): Promise<{ sent?: boolean }> {
157	  // This lookup was ALREADY lowercasing while register/login stored the address
158	  // verbatim, which is precisely why a `Alice@Example.com` signup could never be
159	  // reset. Both sides now share one definition rather than two that agreed by
160	  // luck — see lib/email-normalize.ts.
161	  const email = normalizeEmail(formData.get("email"));
162	  // Throttle per email+IP (same helper login uses) to curb reset-email flooding
163	  // and enumeration probing. On limit, still report success below (no leak).
164	  //
165	  // `clientIp` rather than the first `x-forwarded-for` entry, which is a field
166	  // the CALLER fills in (nginx appends the real address, it does not replace the
167	  // header). Keying on it let one script vary the fake value per request and get
168	  // a fresh 5-attempt allowance every time, which mattered twice over here: it
169	  // uncapped the reset-mail flood AND it removed the cap on the timing probe
170	  // below.
171	  const ip = clientIp(await headers());
172	  const rl = checkRateLimit(`pwreset:${email}:${ip}`, { max: 5, windowMs: 15 * 60 * 1000 });
173	  if (!rl.ok) return { sent: true };
174	  // Always report success (don't leak which emails exist)
175	  const user = await db.user.findUnique({ where: { email } });
176	  if (user) {
177	    const { randomBytes, createHash } = await import("node:crypto");
178	    const token = randomBytes(32).toString("base64url");
179	    const tokenHash = createHash("sha256").update(token).digest("hex");
180	    await db.passwordResetToken.create({
181	      data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
182	    });
183	    const { sendMail, emails } = await import("./mailer");
184	    const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
185	    const tpl = emails.passwordReset(link);
186	    // THE SEND IS DELIBERATELY NOT AWAITED, and that is a security property, not
187	    // an optimisation.
188	    //
189	    // "If an account exists for that email, a reset link is on its way" is the
190	    // right answer and is returned either way — but only ONE of the two branches
191	    // used to open an SMTP conversation before answering. A known address took
192	    // as long as the mail server did; an unknown one returned after a single
193	    // indexed SELECT. The wording revealed nothing and the clock revealed
194	    // everything, one sample per address, which is a working account-enumeration
195	    // oracle against a hosting provider's whole customer list. Detaching the send
196	    // leaves the two branches differing by one INSERT.
197	    //
198	    // Nothing is lost by not waiting: the result was already discarded, and the
199	    // customer was never told whether it worked. Failures are logged, and the
200	    // rejection is swallowed so a dead mail server can never take the process
201	    // down through an unhandled rejection.
202	    //
203	    // `mayDeliverTo` consults the notification policy, which classifies
204	    // `password_reset` as CRITICAL and returns true without even loading the
205	    // preferences. The call is here so the POLICY decides, not this call site: a
206	    // reset link is the only route back into a locked-out account, so honouring
207	    // an "Account email: off" checkbox here would lock the customer out of their
208	    // own account permanently.
209	    void (async () => {
210	      if (await mayDeliverTo(user.id, "password_reset", "email")) {
211	        await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
212	      }
213	    })().catch((e) => {
214	      console.error("[password-reset] send failed:", e);
215	    });
216	    await db.auditLog.create({ data: { userId: user.id, action: "user.password_reset_request" } });
217	  }
218	  return { sent: true };
219	}
220	
221	export async function resetPassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
222	  const token = String(formData.get("token") ?? "");
223	  const password = String(formData.get("password") ?? "");
224	  if (password.length < 8) return { error: "Password must be at least 8 characters." };
225	  const { createHash } = await import("node:crypto");
226	  const tokenHash = createHash("sha256").update(token).digest("hex");
227	  const row = await db.passwordResetToken.findUnique({ where: { tokenHash } });
228	  if (!row || row.usedAt || row.expiresAt < new Date()) {
229	    return { error: "This reset link is invalid or has expired. Request a new one." };
230	  }
231	  await db.$transaction([
232	    // Bump sessionVersion so any sessions predating the reset are evicted.
233	    db.user.update({
234	      where: { id: row.userId },
235	      data: { passwordHash: await bcrypt.hash(password, 12), sessionVersion: { increment: 1 } },
236	    }),
237	    db.passwordResetToken.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
238	    db.auditLog.create({ data: { userId: row.userId, action: "user.password_reset_complete" } }),
239	  ]);
240	  return { ok: true };
241	}
242	
243	/** Admin-triggered reset: emails the client a reset link. */
244	export async function adminSendPasswordReset(userId: string) {
245	  const admin = await requireAdmin();
246	  const user = await db.user.findUnique({ where: { id: userId } });
247	  if (!user) throw new Error("User not found");
248	  const { randomBytes, createHash } = await import("node:crypto");
249	  const token = randomBytes(32).toString("base64url");
250	  const tokenHash = createHash("sha256").update(token).digest("hex");
251	  await db.passwordResetToken.create({
252	    data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
253	  });
254	  const { sendMail, emails } = await import("./mailer");
255	  const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
256	  const tpl = emails.passwordReset(link);
257	  // CRITICAL (see above): support has just told the customer "check your email".
258	  // A preference must not be able to make that a lie.
259	  if (await mayDeliverTo(user.id, "password_reset", "email")) {
260	    await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html });
261	  }
262	  await db.auditLog.create({ data: { userId: admin.id, action: "admin.password_reset_sent", detail: user.email } });
263	}
264	
265	// ---------- Impersonation (admin) ----------
266	
267	export async function impersonateUser(userId: string) {
268	  const admin = await requireAdmin();
269	  const target = await db.user.findUnique({ where: { id: userId } });
270	  if (!target || target.role === "ADMIN") throw new Error("Cannot impersonate this account");
271	  await setImpersonation(userId);
272	  await db.auditLog.create({
273	    data: { userId: admin.id, action: "admin.impersonate_start", detail: `${target.email}` },
274	  });
275	  redirect("/dashboard");
276	}
277	
278	export async function stopImpersonating() {
279	  await clearImpersonation();
280	  redirect("/admin/users");
281	}
