1	import { redirect } from "next/navigation";
2	import { LoginForm } from "@/components/AuthForms";
3	import { AuthShell } from "@/components/marketing/AuthShell";
4	import { currentUser } from "@/lib/auth";
5	import { safeNext } from "@/lib/safe-next";
6	import { googleOauthConfigured } from "@/lib/google-oauth";
7	import { discordOauthConfigured } from "@/lib/discord-oauth";
8	import { roleHome } from "@/lib/portal-home";
9	
10	/** Friendly copy for the `?error=` codes the Google OAuth routes bounce back. */
11	const GOOGLE_ERRORS: Record<string, string> = {
12	  google_unavailable: "Google sign-in isn't set up on this server yet. Use your email and password.",
13	  google_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
14	  google_cancelled: "Google sign-in was cancelled.",
15	  google_state: "That Google sign-in link expired or didn't match. Please try again.",
16	  google_unverified: "Your Google email isn't verified, so we can't sign you in with it.",
17	  google_error: "Couldn't finish signing in with Google. Please try again.",
18	  account_suspended: "This account is suspended.",
19	};
20	
21	/** Friendly copy for the `?error=` codes the Discord OAuth routes bounce back
22	 *  — same convention as GOOGLE_ERRORS above (a fixed code->message map, never
23	 *  echoing a server-derived string straight into the query/DOM). */
24	const DISCORD_ERRORS: Record<string, string> = {
25	  discord_unavailable: "Discord sign-in isn't set up on this server yet. Use your email and password.",
26	  discord_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
27	  discord_cancelled: "Discord connection cancelled.",
28	  discord_state: "That Discord sign-in link expired or didn't match. Please try again.",
29	  discord_unverified_email: "Your Discord account needs a verified email to sign up this way. Verify it on Discord, or create a Nxeon account normally and connect Discord from Settings afterward.",
30	  discord_email_taken: "An account with this email already exists. Log in normally, then connect Discord from Settings.",
31	  discord_suspended: "This account is suspended.",
32	  discord_error: "Couldn't finish signing in with Discord. Please try again.",
33	};
34	
35	export default async function LoginPage({
36	  searchParams,
37	}: {
38	  searchParams: Promise<{ next?: string; error?: string }>;
39	}) {
40	  // Where the visitor was heading before the login wall. Public CTAs pass this so
41	  // signing in lands them on what they actually clicked instead of a generic
42	  // dashboard. Validated by `safeNext` — an unchecked `next` on a login form is an
43	  // open redirect and therefore a phishing primitive — so it is never trusted,
44	  // here or in the action.
45	  const { next, error } = await searchParams;
46	  const dest = safeNext(next ?? null);
47	  // Only ever surface a message from our own fixed map — never echo the raw
48	  // query value into the page.
49	  const googleError = error ? GOOGLE_ERRORS[error] : undefined;
50	  const discordError = error ? DISCORD_ERRORS[error] : undefined;
51	  const discordEnabled = await discordOauthConfigured();
52	
53	  // Already signed in? Then this page is just a waypoint: send them where they
54	  // were going. Without this, a public CTA written as `/login?next=/dashboard/x`
55	  // would strand EXISTING customers on a sign-in form they do not need — trading
56	  // one dead end for a worse one, since it asks a paying customer to authenticate
57	  // twice.
58	  const user = await currentUser();
59	  if (user) redirect(dest ?? roleHome(user.role));
60	
61	  return (
62	    <AuthShell
63	      heading="Welcome back"
64	      sub="Sign in to manage your servers and billing."
65	      bullets={[
66	        "Instant NVMe VPS provisioning",
67	        "Real-time metrics and one-click reinstalls",
68	        "Full root access on every plan",
69	      ]}
70	    >
71	      {/* The VALIDATED destination, never the raw query value: a rejected
72	          `next` must not be echoed into the DOM at all. It could not cause a
73	          redirect (the action re-validates), but rendering attacker-supplied
74	          text into a form for no reason is how the next bug starts. */}
75	      <LoginForm
76	        next={dest ?? undefined}
77	        googleEnabled={googleOauthConfigured()}
78	        googleError={googleError}
79	        discordEnabled={discordEnabled}
80	        discordError={discordError}
81	      />
82	    </AuthShell>
83	  );
84	}
